"use strict";
/* global sharedScriptManager, CryptoJS */

var CRMLoginManager = CRMLoginManager || {};

CRMLoginManager = {
    checkBrowser: function () {
        var msieVersion = sharedScriptManager.getIeVersion();
        if (msieVersion !== -1 && msieVersion < 8.0) {
            $('#not-supported-browser-panel').show();
        }
    },

    trimString: function (stringValue) {
        return stringValue.replace(/^\s+|\s+$/g, '');
    },

    encyptPassword: function () {
        var pwdInDb = CryptoJS.CfsEnCode($('#password').val());
        // loginToken is a random string generated by server code, 
        // and it must be submitted back to server.
        var loginToken = $("#loginToken").val();
        // in order to create randomlty a string before submitting to server 
        // we use SHA256 algorithm to hash a pwdInDb+loginToken
        var hashPassword = CryptoJS.SHA256(pwdInDb + loginToken);

        $('#password').val(hashPassword);
    },

    validateInput: function () {
        var $username = $('#username');
        var $password = $('#password');
        $username.val(CRMLoginManager.trimString($username.val()));
        $username.removeClass('err');
        $username.removeClass('err');

        if ($username.val().length === 0) {
            $username.addClass('err');
            return false;
        }

        if ($password.val().length === 0) {
            $password.addClass('err');
            return false;
        }

        return true;
    },

    blockComponent: function () {
        $('#username, #password').removeClass('err');
        $('#btnSubmit').prop('disabled', true);
    },
    
    init: function () {
        CRMLoginManager.checkBrowser();
        $('#msg').toggle($('#inner-msg').html().length > 0);
        $('#username').focus();

        if ($(window.parent.document).find('iframe').length > 0) {
            window.parent.location.href = location.href;
            return;
        }

        document.forms[0].onsubmit = function () {
            $('#msg').hide();

            if (!CRMLoginManager.validateInput()) {
                return false;
            }

            CRMLoginManager.blockComponent();
            CRMLoginManager.encyptPassword();
            return true;
        };
    }
};

$(document).ready(function () {
    CRMLoginManager.init();
});